 "<b style=\"font-size:27px;color:#2f9a86\">Social</b><br><span style=\"font-size:22px;color:#25193a\">Excluir, esparcir rumores, ignorar.</span>": "<b style=\"font-size:27px;color:#2f9a86\">Social</b><br><span style=\"font-size:22px;color:#25193a\">Excluír, espallar rumores, ignorar.</span>",
 "<b style=\"font-size:27px;color:#c8456f\">Digital</b><br><span style=\"font-size:22px;color:#25193a\">Mensajes, fotos o grupos para humillar.</span>": "<b style=\"font-size:27px;color:#c8456f\">Dixital</b><br><span style=\"font-size:22px;color:#25193a\">Mensaxes, fotos ou grupos para humillar.</span>",
